package com.aistock.prediction.question;
import com.aistock.prediction.analysis.AnalysisRepository;import com.aistock.prediction.explanation.MaasClient;import java.util.*;import java.time.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static com.aistock.prediction.question.QuestionSamples.*;
class QuestionServiceTest {
 @Test void replayBeforeDependencies(){var r=mock(QuestionRepository.class);var src=mock(AnalysisRepository.class);var client=mock(MaasClient.class);var in=new QuestionInput(UUID.randomUUID(),UUID.randomUUID(),"风险？");var u=UUID.randomUUID();when(r.replay(eq(u),eq(in),any())).thenReturn(M.createObjectNode().put("state","SUCCEEDED"));assertEquals("SUCCEEDED",new QuestionService(r,src,client,M,Clock.systemUTC()).generate(u,in).path("state").asText());verifyNoInteractions(src,client);}
 @Test void invalidOutputPreservesPrevious(){var r=mock(QuestionRepository.class);var src=mock(AnalysisRepository.class);var client=mock(MaasClient.class);var u=UUID.randomUUID();var in=new QuestionInput(UUID.randomUUID(),UUID.fromString(analysis(false).path("analysisId").asText()),"风险？");when(src.get(u,in.analysisId())).thenReturn(analysis(false));when(client.enabled()).thenReturn(true);when(client.model()).thenReturn("test");when(r.claim(any(),any(),any(),any())).thenReturn(new QuestionRepository.Claim(true,M.createObjectNode()));when(client.generateQuestion(anyString(),anyMap())).thenReturn(raw("RISK","准确率99%{{BASIS_LIMIT}}","BASIS_LIMIT"));new QuestionService(r,src,client,M,Clock.systemUTC()).generate(u,in);verify(r).complete(eq(in.operationId()),isNull(),eq("AI_OUTPUT_INVALID"),any());}
}
